#define cr(v, n) (v).clear(), (v).resize(n);

vector<int> pa;

int find(int x) { return pa[x] = (pa[x] == x ? x : find(pa[x])); }

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);
	int T; cin>>T;
	while (T--){
		int n;
		cin >> n;
		vector<array<lint, 3>> edges;
		for (int i = 0; i < n - 1; i++) {
			lint u, v, w;
			cin >> u >> v >> w;
			u--;
			v--;
			edges.push_back({w, u, v});
		}
		sort(all(edges));
		reverse(all(edges));
		cr(pa, 2 * n - 1);
		vector<lint> cost(2 * n - 1);
		vector<pi> ch(2 * n - 1);
		iota(all(pa), 0);
		for (int i = 0; i < n - 1; i++) {
			int u = find(edges[i][1]);
			int v = find(edges[i][2]);
			pa[u] = i + n;
			pa[v] = i + n;
			ch[i + n] = {u, v};
			cost[edges[i][1]] += edges[i][0];
			cost[edges[i][2]] += edges[i][0];
			cost[i + n] -= edges[i][0] * 2;
		}
		for (int i = n; i < 2 * n - 1; i++) {
			cost[i] += cost[ch[i][0]] + cost[ch[i][1]];
		}
		int q;
		cin >> q;
		while (q--) {
			lint x;
			cin >> x;
			vector<lint> dp(2 * n - 1);
			lint dap = 0;
			for (int i = 0; i < 2 * n - 1; i++) {
				if (i >= n) {
					dp[i] += dp[ch[i][0]] + dp[ch[i][1]];
				}
				if (dp[i] + cost[i] < x) {
					dap += x - cost[i] - dp[i];
					dp[i] = x - cost[i];
				}
			}
			cout << dap << "\n";
		}
	}
}

#include <bits/stdc++.h>
using namespace std;
using lint = long long;
using pi = array<lint, 2>;
#define sz(v) ((int)(v).size())
#define all(v) (v).begin(), (v).end()
#define cr(v, n) (v).clear(), (v).resize(n);

vector<int> pa;

int find(int x) { return pa[x] = (pa[x] == x ? x : find(pa[x])); }

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);
	int T; cin>>T;
	while (T--){
		int n;
		cin >> n;
		vector<array<lint, 3>> edges;
		for (int i = 0; i < n - 1; i++) {
			lint u, v, w;
			cin >> u >> v >> w;
			u--;
			v--;
			edges.push_back({w, u, v});
		}
		sort(all(edges));
		reverse(all(edges));
		cr(pa, 2 * n - 1);
		vector<lint> cost(2 * n - 1);
		vector<pi> ch(2 * n - 1);
		iota(all(pa), 0);
		for (int i = 0; i < n - 1; i++) {
			int u = find(edges[i][1]);
			int v = find(edges[i][2]);
			pa[u] = i + n;
			pa[v] = i + n;
			ch[i + n] = {u, v};
			cost[edges[i][1]] += edges[i][0];
			cost[edges[i][2]] += edges[i][0];
			cost[i + n] -= edges[i][0] * 2;
		}
		for (int i = n; i < 2 * n - 1; i++) {
			cost[i] += cost[ch[i][0]] + cost[ch[i][1]];
		}
		// (point, slope increase)
		vector<priority_queue<pi, vector<pi>, greater<pi>>> pq(n);
		vector<int> idx(2 * n - 1);
		iota(all(idx), 0);
		for (int i = 0; i < 2 * n - 1; i++) {
			if (i < n) {
				pq[i].push({cost[i], 1});
				continue;
			}
			if (sz(pq[idx[ch[i][0]]]) < sz(pq[idx[ch[i][1]]]))
				swap(ch[i][0], ch[i][1]);
			idx[i] = idx[ch[i][0]];
			while (sz(pq[idx[ch[i][1]]])) {
				auto tp = pq[idx[ch[i][1]]].top();
				pq[idx[ch[i][1]]].pop();
				pq[idx[i]].push(tp);
			}
			if (cost[i] >= pq[idx[i]].top()[0])
				continue;
			if (cost[i] >= lint(2e9))
				continue;
			lint A = 0, B = 0;
			lint pv = -1;
			while (sz(pq[idx[i]])) {
				auto [point, slope] = pq[idx[i]].top();
				pq[idx[i]].pop();
				B += A * (point - pv);
				pv = point;
				A += slope;
				// A x - A * pv + B = x - cost[i]
				// (A - 1) x = A * pv - B - cost[i]
				lint U = A * pv - B - cost[i];
				lint L = A - 1;
				// point <= U / L, so no need to dedup
				if (L > 0) {
					assert(point * L <= U);
					if ((sz(pq[idx[i]]) == 0 || U < pq[idx[i]].top()[0] * L)) {
						lint f1 = U / L - cost[i];
						lint f2 = (U / L + 1 - pv) * A + B;
						// (cost[i], 0) -> (U / L, f1) -> (U / L + 1, f2) -> increase w/ speed A
						pq[idx[i]].push({cost[i], 1});
						pq[idx[i]].push({U / L, f2 - f1 - 1});
						pq[idx[i]].push({U / L + 1, A - (f2 - f1)});
						break;
					}
				} else if (sz(pq[idx[i]]) == 0) {
					pq[idx[i]].push({cost[i], 1});
					break;
				}
			}
		}
		int q;
		cin >> q;
		vector<pi> queries(q);
		for (int i = 0; i < q; i++) {
			cin >> queries[i][0];
			queries[i][1] = i;
		}
		sort(all(queries));
		vector<lint> ans(q);
		lint A = 0, B = 0, pv = -1;
		auto T = idx[2 * n - 2];
		for (auto &[x, i] : queries) {
			while (sz(pq[T]) && pq[T].top()[0] <= x) {
				auto [point, slope] = pq[T].top();
				pq[T].pop();
				B += A * (point - pv);
				pv = point;
				A += slope;
			}
			ans[i] = (x - pv) * A + B;
		}
		for (auto &v : ans)
			cout << v << "\n";
	}
}
